# Re-date an OPEN or PENDING claim (a steward). A date after its person's retirement, a claim due
# by a date inside a closed period, or anyone but a steward is refused and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateRedate
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.RedateClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRedated
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Move the selected claims to one person together, in list order, by the rules of moving one. Each
# that cannot be moved is refused and left as it is; the response tells how many were moved and how
# many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkReassign
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: reassign
# Each claim moved is audited as it is moved: its own line, then the figures it moved.
reassign:
  class: net.officefloor.hq.app.claim.ReassignSelectedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkReassign
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-dates an OPEN or PENDING claim (a steward). Its new date may not be after its person's
 * retirement. Its due-by and any figure a statement bound it to are kept, and so its period (the one
 * containing its due-by) and its number: a new date inside a closed period is allowed.
 */
public class RedateClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val Redate redate, PersonRepository people,
            RoleRepository roles, HttpServletRequest request, Out<Redating> redatingOut)
            throws StewardOnlyException, InvalidClaimStatusException, RetiredPersonException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), Audit.user(request)))) {
            throw new StewardOnlyException("Only a steward may re-date a claim");
        }
        if (!claim.isOpen()) {
            throw new InvalidClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        LocalDate to = redate.date();
        Person person = people.find(sheet.id(), claim.getPersonId());
        if (person != null && person.retiredBefore(to)) throw new RetiredPersonException(person.getName());

        LocalDate from = claim.getDate();
        claim.setDate(to);
        redatingOut.set(new Redating(from, to));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A re-dating as validated: the claim's new date. */
public record Redate(LocalDate date) {
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the re-dating, naming the claim with its new date; the line ends with its old and new dates. */
public class AuditClaimRedated {
    public void audit(@Val Sheet sheet, @Val Claim claim, @Val Redating redating, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_REDATED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " old=" + redating.from() + " new=" + redating.to());
    }
}
package net.officefloor.hq.app.claim;

/** A re-dating as the screen sends it: the claim's new date (yyyy-MM-dd). */
public record RedateRequest(String date) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A re-dating needs the claim's new date. */
public class ValidateRedate {
    public void validate(@RequestBody RedateRequest request, Out<Redate> body) throws InvalidClaimException {
        String raw = request == null || request.date() == null ? "" : request.date().trim();
        try {
            body.set(new Redate(LocalDate.parse(raw)));
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("A re-dating needs the claim's new date");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A claim's re-dating: the date it had and the date it has now. */
public record Redating(LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** A bulk move as the screen sends it: the ids of the selected claims and the id of the person they move to. */
public record BulkReassignRequest(List<String> claimIds, String personId) {
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims were moved, and how many were refused and left as they were. */
public record BulkReassignResponse(int reassigned, int refused) {
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the selected claims to one person in list order (people by their position in the list, each
 * person's claims newest first, as listed before any is moved) by the rules of moving one claim, as
 * the signed-in user. A claim that cannot be moved (a role the permission matrix does not allow, a
 * SETTLED or VOID claim, its due-by inside a closed period, dated after the person's retirement, the
 * person not on the sheet) is refused and left as it is. Each claim moved is audited as a single move
 * is: its CLAIM_REASSIGNED line, then the figures it moved. A viewer, or anyone on an archived sheet,
 * moves none: every selected claim is refused.
 */
public class ReassignSelectedClaims {
    public void reassign(@Val Sheet sheet, @Val BulkReassignRequest request, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
            RoleRepository roles, SettingsRepository settings, HttpServletRequest http, Audit audit,
            Out<BulkReassignResponse> result) {
        String user = Audit.user(http);
        Set<Long> selected = new HashSet<>();
        for (String id : request.claimIds()) {
            try {
                selected.add(Long.parseLong(id.trim()));
            } catch (NumberFormatException | NullPointerException e) {
                // not an id: no claim on the sheet, so refused below
            }
        }
        int requested = new HashSet<>(request.claimIds()).size();
        Person to = null;
        try {
            to = people.find(sheet.id(), Long.parseLong(request.personId()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (sheet.archived() || to == null || !settings.find(sheet.id()).allows("reassign", roles.roleOf(sheet.id(), user))) {
            result.set(new BulkReassignResponse(0, requested)); // nothing may be moved: every claim refused
            return;
        }
        List<Claim> listed = new ArrayList<>();
        for (Person person : people.findAll(sheet.id())) {
            for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
                if (selected.contains(claim.getId())) listed.add(claim);
            }
        }
        int reassigned = 0;
        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
        for (Claim claim : listed) {
            if (periods.closedOn(sheet.id(), claim.getDueBy()) != null) continue;
            if (to.retiredBefore(claim.getDate())) continue;
            Person from = people.find(sheet.id(), claim.getPersonId());
            try {
                claim.reassign(to.getId());
            } catch (InvalidClaimStatusException e) {
                continue;
            }
